import { world, system, PlayerPermissionLevel } from "@minecraft/server";
import { CustomForm as MinecraftCustomForm, MessageFormData, ObservableString, ObservableBoolean, ObservableNumber } from "@minecraft/server-ui";

// DDUI buttons do not automatically dismiss a CustomForm. Wrap the stable API so every
// button explicitly closes its current form and defers its handler out of the UI callback.
// This prevents the visible form from sitting on-screen and intercepting subsequent menus.
class CustomForm extends MinecraftCustomForm {
  button(label, onClick, options) {
    const buttonLabel = typeof label === "string" ? label.replace(/§./g, "") : label;
    return super.button(buttonLabel, () => {
      try { this.close(); } catch {}
      system.run(() => {
        try { onClick(); } catch (e) { console.warn(`[Transfer UI] button handler failed: ${e?.stack ?? e}`); }
      });
    }, options);
  }
}

import { transferPlayer } from "@minecraft/server-admin";


const PACK="Transfer UI", DATA_KEY="transferhub:data", BACKUP_KEY="transferhub:backup", DRAFT_KEY="transferhub:draft", AUDIT_KEY="transferhub:audit";
const FAV_KEY="transferhub:favorites", PREF_KEY="transferhub:prefs", HISTORY_KEY="transferhub:history";
const DATA_VERSION=4, MAX_NODES=180, MAX_AUDIT=80;
const DEF={version:DATA_VERSION,revision:1,settings:{title:"§b§lServer Network",subtitle:"Choose a destination.",openerItem:"minecraft:compass",showDirectConnect:false,confirmTransfers:true,maxRecent:8},nodes:[{id:"main",type:"folder",parentId:null,name:"Main Servers",description:"Official network destinations",order:0,enabled:true}],announcements:[]};
const clone=v=>JSON.parse(JSON.stringify(v));
const parse=(v,f)=>{try{return typeof v==="string"?JSON.parse(v):f}catch{return f}};
const clean=s=>`${s??""}`.trim();
const idFrom=s=>clean(s).toLowerCase().replace(/§./g,"").replace(/[^a-z0-9_-]+/g,"-").replace(/^-+|-+$/g,"").slice(0,32)||`node-${Date.now()}`;
const unique=(items,want)=>{let x=want,n=2;const u=new Set(items.map(v=>v.id));while(u.has(x))x=`${want}-${n++}`;return x};
const later=fn=>system.run(fn), info=(p,m)=>p.sendMessage(`§a[Transfer UI] ${m}`), err=(p,m)=>p.sendMessage(`§c[Transfer UI] ${m}`);
const isAdmin=p=>{try{return p.playerPermissionLevel===PlayerPermissionLevel.Operator}catch{return false}};
function normalize(raw){const d=raw&&typeof raw==="object"?raw:clone(DEF);if(Array.isArray(d.categories)||Array.isArray(d.servers)){const nodes=[];for(const c of d.categories??[])nodes.push({id:c.id,type:"folder",parentId:null,name:c.name,description:c.description??"",order:c.order??0,enabled:true});for(const s of d.servers??[])nodes.push({...s,type:"server",parentId:s.categoryId??"main",tags:s.tags??[],region:s.region??"",gameMode:s.gameMode??"",recommended:!!s.recommended,maintenance:!!s.maintenance,requirements:s.requirements??{}});d.nodes=nodes;delete d.categories;delete d.servers}d.version=DATA_VERSION;d.revision=Number(d.revision)||1;d.settings={...DEF.settings,...(d.settings??{})};d.nodes=Array.isArray(d.nodes)?d.nodes:clone(DEF.nodes);d.announcements=Array.isArray(d.announcements)?d.announcements:[];if(!d.nodes.some(n=>n.type==="folder"))d.nodes.unshift(clone(DEF.nodes[0]));for(const n of d.nodes){n.id=n.id||unique(d.nodes,idFrom(n.name));n.type=["folder","server","info"].includes(n.type)?n.type:"info";n.parentId=n.parentId??null;n.name=n.name||"Untitled";n.description=n.description??"";n.order=Number(n.order)||0;n.enabled=n.enabled!==false;if(n.type==="server"){n.tags=Array.isArray(n.tags)?n.tags:[];n.requirements=n.requirements&&typeof n.requirements==="object"?n.requirements:{};n.cooldownSeconds=Math.max(0,Number(n.cooldownSeconds)||0)}}return d}
function getPublished(){return normalize(parse(world.getDynamicProperty(DATA_KEY),clone(DEF)))}
function savePublished(d,actor="system",action="publish"){const next=normalize(d),text=JSON.stringify(next);if(text.length>30000)throw Error("Configuration exceeds 30,000 characters.");const old=world.getDynamicProperty(DATA_KEY);if(typeof old==="string")world.setDynamicProperty(BACKUP_KEY,old);world.setDynamicProperty(DATA_KEY,text);audit(actor,action,`revision ${next.revision}`)}
function getDraft(){const v=world.getDynamicProperty(DRAFT_KEY);return typeof v==="string"?normalize(parse(v,getPublished())):clone(getPublished())}
function saveDraft(d){const t=JSON.stringify(normalize(d));if(t.length>30000)throw Error("Draft exceeds 30,000 characters.");world.setDynamicProperty(DRAFT_KEY,t)}
function audit(actor,action,detail=""){const a=parse(world.getDynamicProperty(AUDIT_KEY),[]);a.unshift({time:new Date().toISOString(),actor:typeof actor==="string"?actor:actor?.name??"system",action,detail});world.setDynamicProperty(AUDIT_KEY,JSON.stringify(a.slice(0,MAX_AUDIT)))}
function pjson(p,key,f){return parse(p.getDynamicProperty(key),clone(f))}function pset(p,key,v){p.setDynamicProperty(key,JSON.stringify(v))}
const favs=p=>pjson(p,FAV_KEY,[]);const prefs=p=>({...{home:null,confirmMode:"default"},...pjson(p,PREF_KEY,{})});const hist=p=>pjson(p,HISTORY_KEY,[]);
function visible(p,n){if(n.enabled===false)return false;const r=n.requirements??{};if(r.adminOnly&&!isAdmin(p))return false;if(r.tag&&!p.hasTag(r.tag))return false;if(r.notTag&&p.hasTag(r.notTag))return false;if(r.dimension&&p.dimension?.id!==r.dimension)return false;if(r.scoreObjective){try{const o=world.scoreboard.getObjective(r.scoreObjective);const s=o?.getScore(p.scoreboardIdentity);if(s===undefined)return false;if(r.minScore!==undefined&&s<Number(r.minScore))return false;if(r.maxScore!==undefined&&s>Number(r.maxScore))return false}catch{return false}}return true}
function children(data,parent,p){const local=data.nodes.filter(n=>(n.parentId??null)===(parent??null)&&visible(p,n));const external=parent===null?providerChildren(null,p):[];return [...local,...external].sort((a,b)=>(a.order??0)-(b.order??0)||a.name.localeCompare(b.name))}
function recordVisit(p,id){const d=getPublished(),max=d.settings.maxRecent??8;const h=hist(p).filter(x=>x.id!==id);h.unshift({id,time:Date.now()});pset(p,HISTORY_KEY,h.slice(0,max));const pr=prefs(p);pr.last=id;pset(p,PREF_KEY,pr)}
const cooldowns=new Map();
async function doTransfer(p,n,ctx={depth:0,requestId:requestId("transfer")}){try{apiMetrics.transfersRequested++;const live=resolveDestination(n.id)||n;if(live.providerId&&!destinationAvailable(live))return err(p,"This destination is currently unavailable.");if(live.providerMeta?.maxPlayers!=null&&finite(live.providerMeta.players)>=finite(live.providerMeta.maxPlayers)&&!isAdmin(p))return err(p,"This destination is currently full.");emitLifecycle("requested",p,live,{requestId:ctx.requestId});const policy=await runPolicies(p,live,ctx.requestId);if(policy.result==="deny"){apiMetrics.transfersDenied++;emitLifecycle("denied",p,live,{requestId:ctx.requestId,reason:policy.reason??"Denied by policy",providerId:policy.providerId});return err(p,policy.reason||"This transfer is not currently allowed.")}if(policy.result==="redirect"){if(ctx.depth>=API_LIMITS.maxRedirects){apiMetrics.transfersDenied++;return err(p,"Transfer redirect limit reached.")}const target=resolveDestination(policy.destinationId);if(target&&target.id!==live.id){apiMetrics.transfersRedirected++;emitLifecycle("redirected",p,live,{requestId:ctx.requestId,to:target.id,providerId:policy.providerId});return doTransfer(p,target,{...ctx,depth:ctx.depth+1})}}const latest=resolveDestination(live.id)||live;if(latest.providerId&&!destinationAvailable(latest))return err(p,"This destination changed and is no longer available.");const k=`${p.id}:${latest.id}`,t=Date.now(),until=cooldowns.get(k)??0;if(t<until)return err(p,`Please wait ${Math.ceil((until-t)/1000)}s before using this destination again.`);cooldowns.set(k,t+(latest.cooldownSeconds??2)*1000);recordVisit(p,latest.id);emitLifecycle("started",p,latest,{requestId:ctx.requestId});if(latest.netherNetId)transferPlayer(p,{netherNetId:latest.netherNetId});else{const port=Number(latest.port);if(!latest.hostname||!Number.isInteger(port)||port<1||port>65535)throw Error("Invalid hostname or port.");transferPlayer(p,{hostname:latest.hostname,port})}apiMetrics.transfersDispatched++;info(p,`Connecting to ${latest.name}...`);emitLifecycle("dispatched",p,latest,{requestId:ctx.requestId})}catch(e){emitLifecycle("failed",p,n,{requestId:ctx.requestId,error:`${e?.message??e}`});err(p,`Transfer failed: ${e?.message??e}`)}}
function connect(p,n){if(n.maintenance&&!isAdmin(p))return err(p,"This destination is currently in maintenance mode.");const pr=prefs(p),confirm=pr.confirmMode==="always"||(pr.confirmMode==="default"&&getPublished().settings.confirmTransfers);if(!confirm)return void doTransfer(p,n);new MessageFormData().title("§b§lConfirm Transfer").body(`Connect to ${n.name}?${n.maintenance?"\n§eMaintenance mode is enabled.":""}`).button1("Connect").button2("Cancel").show(p).then(r=>{if(!r.canceled&&r.selection===0)doTransfer(p,n);else emitLifecycle("cancelled",p,n)}).catch(e=>console.warn(`[${PACK}] confirm transfer UI failed: ${e}`))}
function nodeDetail(p,n,parent){const f=favs(p),pr=prefs(p),isFav=f.includes(n.id);const form=new CustomForm(p,n.name).label(n.description||"No description");if(n.type==="server"){const meta=[n.gameMode,n.region,...(n.tags??[])].filter(Boolean).join(" • ");if(meta)form.label(`§7${meta}`);if(n.announcement)form.label(`§e${n.announcement}`);if(n.providerMeta?.status)form.label(`§b${n.providerMeta.status}${n.providerMeta.players!==undefined?` §8• §f${n.providerMeta.players} player(s)`:""}`);form.divider().button(n.maintenance?"Connect (Maintenance)":"Connect",()=>connect(p,n));form.button(isFav?"Remove Favorite":"Add Favorite",()=>{let a=favs(p);a=isFav?a.filter(x=>x!==n.id):[...new Set([...a,n.id])];pset(p,FAV_KEY,a);later(()=>nodeDetail(p,n,parent))}).button(pr.home===n.id?"Clear Home":"Set Home",()=>{const x=prefs(p);x.home=x.home===n.id?null:n.id;pset(p,PREF_KEY,x);later(()=>nodeDetail(p,n,parent))})}else if(n.type==="folder")form.divider().button("Open",()=>later(()=>showFolder(p,n.id)));form.divider().button("Back",()=>later(()=>showFolder(p,parent))).closeButton().show().catch(e=>console.warn(`[${PACK}] DDUI show failed: ${e}`))}
function addNodeButton(form,p,n,parent){let desc=n.description?`\n${n.description.slice(0,62)}`:"";if(n.providerMeta?.status){const count=n.providerMeta.players!==undefined?` • ${n.providerMeta.players} player(s)`:"";const detail=n.description?`\n§7${n.description.slice(0,58)}`:"";desc=`\n§b${n.providerMeta.status}§f${count}${detail}`;}form.button(`${n.name}${desc}`,()=>later(()=>n.type==="folder"?showFolder(p,n.id):nodeDetail(p,n,parent)))}

// Transfer UI Provider API 1.0.0. Keep this protocol version frozen until an explicit release bump.
// ScriptEvent is an interoperability bus, not a hostile-addon security boundary: all payloads are validated,
// namespaced and capability-gated, but another installed script can observe/emit ScriptEvents.
const PROVIDER_PROTOCOL=1, API_VERSION="1.0.0";
const API_LIMITS={maxProviders:32,maxDestinationsPerProvider:512,maxPresencePerProvider:2048,maxGroupsPerProvider:256,maxRelationshipsPerProvider:4096,maxActionsPerProvider:128,maxSectionsPerProvider:128,maxTags:32,maxMetadataChars:8192,maxIpcChars:262144,maxChunks:256,chunkChars:1400,chunkTtlMs:30000,providerStaleMs:90000,policyTicks:20,maxRedirects:4,maxQueuedEvents:1024,maxEventsPerTick:8};
const CAPABILITIES=new Set(["destinations","destination-deltas","presence","presence-deltas","relationships","groups","navigation","actions","policies","health","transfer-lifecycle","transfer-requests","deep-links","metadata","selection","queues","configure"]);
const providers=new Map(), providerNodes=new Map(), presence=new Map(), relationships=new Map(), groups=new Map(), navSections=new Map(), providerActions=new Map(), policyProviders=new Map(), providerHealth=new Map(), aliases=new Map(), revisions=new Map(), providerTransactions=new Map();
const ipcChunks=new Map(), policyPending=new Map(), apiEventQueue=[]; let ipcSeq=0;
const apiMetrics={rx:0,tx:0,invalid:0,rejected:0,chunksRx:0,chunksTx:0,chunkTimeouts:0,policyTimeouts:0,transfersRequested:0,transfersDenied:0,transfersRedirected:0,transfersDispatched:0,queued:0,processed:0,dropped:0,queueHighWater:0,handlerErrors:0,lastError:""};
const now=()=>Date.now(), requestId=(prefix="tu")=>`${prefix}-${now()}-${++ipcSeq}`;
const finite=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;
function apiReject(reason){apiMetrics.invalid++;apiMetrics.rejected++;apiMetrics.lastError=clean(reason).slice(0,240);return null}
function metadataOk(v){try{return v===undefined||JSON.stringify(v).length<=API_LIMITS.maxMetadataChars}catch{return false}}
function validProviderId(v){return /^[a-z0-9][a-z0-9._-]{0,63}$/i.test(clean(v))}
function validRevision(id,kind,rev){if(rev===undefined||rev===null)return true;const n=finite(rev,-1),k=`${id}:${kind}`,old=revisions.get(k)??-1;if(n<=old)return false;revisions.set(k,n);return true}
function providerHas(id,cap){const p=providers.get(id);return !!p&&((p.capabilities??[]).includes(cap)||(cap==="health"))}
function sendIpc(id,payload,streamId=requestId("evt")){let text;try{text=JSON.stringify(payload)}catch{return}if(text.length>API_LIMITS.maxIpcChars)return;const total=Math.max(1,Math.ceil(text.length/API_LIMITS.chunkChars));if(total>API_LIMITS.maxChunks)return;apiMetrics.tx++;apiMetrics.chunksTx+=total;for(let i=0;i<total;i++)system.sendScriptEvent(id,JSON.stringify({__tui:1,id:streamId,chunk:i,total,data:text.slice(i*API_LIMITS.chunkChars,(i+1)*API_LIMITS.chunkChars)}));}
function receiveIpc(id,msg){apiMetrics.rx++;if(typeof msg!=="string"||msg.length>4096)return apiReject("IPC frame too large");let x;try{x=JSON.parse(msg)}catch{return apiReject("Malformed JSON")}if(!x?.__tui)return x;if(!Number.isInteger(x.chunk)||!Number.isInteger(x.total)||x.chunk<0||x.total<1||x.total>API_LIMITS.maxChunks||x.chunk>=x.total||typeof x.data!=="string")return apiReject("Invalid chunk frame");apiMetrics.chunksRx++;const key=`${id}:${clean(x.id).slice(0,96)}`;let state=ipcChunks.get(key);if(state&&state.total!==x.total){ipcChunks.delete(key);return apiReject("Chunk stream shape changed")}state=state??{parts:new Array(x.total),total:x.total,created:now(),bytes:0};if(state.parts[x.chunk]===undefined){state.parts[x.chunk]=x.data;state.bytes+=x.data.length}if(state.bytes>API_LIMITS.maxIpcChars){ipcChunks.delete(key);return apiReject("Chunk stream too large")}ipcChunks.set(key,state);if(state.parts.some(v=>v===undefined))return null;ipcChunks.delete(key);try{return JSON.parse(state.parts.join(""))}catch{return apiReject("Reassembled JSON invalid")}}
function providerNodeList(){return [...providerNodes.values()].flatMap(x=>[...x.values()])}
function allPublishedNodes(){return [...getPublished().nodes,...providerNodeList()]}
function providerChildren(parent,p){return providerNodeList().filter(n=>(n.parentId??null)===(parent??null)&&visible(p,n))}
function providerSummary(x){const h=providerHealth.get(x.id)??{};return {id:x.id,name:x.name,version:x.version??"",protocol:x.protocol,apiVersion:API_VERSION,priority:x.priority??0,capabilities:x.capabilities??[],state:h.state??"registered",lastSeen:h.lastSeen??x.lastSeen??0,destinations:providerNodes.get(x.id)?.size??0,presence:presence.get(x.id)?.size??0,configure:x.configure??null}}
function requestProviderConfigure(p,id){
 const x=providers.get(id);if(!x||!providerHas(id,"configure"))return err(p,"This provider does not expose configuration.");
 const rid=requestId("configure");
 console.info(`[${PACK}] requesting provider configuration: provider=${id}, player=${p.name}, request=${rid}`);
 sendIpc("transferui:provider:configure",{protocol:PROVIDER_PROTOCOL,apiVersion:API_VERSION,providerId:id,player:{id:p.id,name:p.name},requestId:rid});
}
function emitProviderStatus(targetId){const payload={protocol:PROVIDER_PROTOCOL,apiVersion:API_VERSION,transferUiVersion:"3.0.0",providers:[...providers.values()].map(providerSummary),limits:API_LIMITS,capabilities:[...CAPABILITIES],metrics:{...apiMetrics,queueDepth:apiEventQueue.length,pendingChunks:ipcChunks.size,pendingPolicies:policyPending.size}};sendIpc("transferui:status",targetId?{...payload,targetId}:payload)}
function normalizeProviderDestination(providerId,x){if(!x||typeof x!=="object"||!metadataOk(x.metadata))return null;const rawId=clean(x.id||x.name).slice(0,96);if(!rawId)return null;const id=`provider:${providerId}:${rawId}`,target=x.target&&typeof x.target==="object"?x.target:{},type=clean(target.type||x.transferType||(x.netherNetId?"nethernet":"bedrock")).toLowerCase();if(!["bedrock","nethernet"].includes(type))return null;const ttl=Math.max(0,finite(x.ttlMs,0));const tags=Array.isArray(x.tags)?x.tags.slice(0,API_LIMITS.maxTags).map(clean).filter(Boolean):[];return {id,externalId:rawId,type:"server",parentId:x.parentId?`provider:${providerId}:${clean(x.parentId).slice(0,96)}`:null,name:clean(x.name).slice(0,96)||"Server",description:clean(x.description).slice(0,512),hostname:clean(target.host||x.hostname).slice(0,255),port:finite(target.port??x.port,19132),netherNetId:clean(target.netherNetId||target.id||x.netherNetId).slice(0,255),transferType:type,enabled:x.enabled!==false,maintenance:!!x.maintenance,tags,region:clean(x.region).slice(0,64),gameMode:clean(x.gameMode).slice(0,64),cooldownSeconds:Math.max(0,Math.min(300,finite(x.cooldownSeconds,2))),providerId,providerPriority:providers.get(providerId)?.priority??0,expiresAt:ttl?now()+ttl:null,providerMeta:{status:clean(x.status).slice(0,64),players:x.playerCount,maxPlayers:x.maxPlayers,version:clean(x.version).slice(0,64),latency:x.latency??null,queue:x.queue??null,featured:!!x.featured,capabilities:Array.isArray(x.capabilities)?x.capabilities.slice(0,32).map(clean):[],raw:x.metadata??{}}}}
function ensureProvider(id,cap){id=clean(id);if(!id||!providers.has(id))return null;if(cap&&!providerHas(id,cap)){apiReject(`Provider ${id} lacks ${cap}`);return null}return id}
function upsertDestinations(id,list){if(!Array.isArray(list))return;const map=providerNodes.get(id)??new Map();for(const v of list.slice(0,API_LIMITS.maxDestinationsPerProvider)){const n=normalizeProviderDestination(id,v);if(n?.externalId&&(n.netherNetId||n.hostname))map.set(n.externalId,n)}providerNodes.set(id,map)}
function snapshotDestinations(id,list){providerNodes.set(id,new Map());upsertDestinations(id,list)}
function presenceMap(id){let m=presence.get(id);if(!m){m=new Map();presence.set(id,m)}return m}
function playerKey(x){return clean(x?.xuid||x?.id||x?.name).slice(0,128)}
function normalizePresence(id,x){if(!x||typeof x!=="object"||!metadataOk(x.metadata))return null;return {...x,id:playerKey(x),providerId:id,name:clean(x.name).slice(0,96)||"Unknown",destinationId:clean(x.destinationId).slice(0,128),status:clean(x.status).slice(0,32)||"online",lastSeen:finite(x.lastSeen,now()),metadata:x.metadata??{}}}
function snapshotPresence(id,list){const m=new Map();for(const x of (Array.isArray(list)?list:[]).slice(0,API_LIMITS.maxPresencePerProvider)){const p=normalizePresence(id,x);if(p?.id)m.set(p.id,p)}presence.set(id,m)}
function allPresence(){return [...presence.values()].flatMap(m=>[...m.values()])}
function presenceByRef(ref){const r=clean(ref).toLowerCase();return allPresence().find(x=>clean(x.id).toLowerCase()===r||clean(x.xuid).toLowerCase()===r||clean(x.name).toLowerCase()===r)||null}
function localPlayerKey(p){return {id:clean(p?.id),name:clean(p?.name).toLowerCase(),xuid:clean(p?.xuid)}}
function relationTouchesPlayer(r,p){const k=localPlayerKey(p),vals=[r?.ownerId,r?.ownerXuid,r?.ownerName,r?.sourceId,r?.sourceXuid,r?.sourceName,r?.playerId,r?.playerXuid,r?.playerName].map(v=>clean(v).toLowerCase()).filter(Boolean);return vals.includes(k.id.toLowerCase())||vals.includes(k.name)||(k.xuid&&vals.includes(k.xuid.toLowerCase()))}
function relationOtherRef(r,p){const k=localPlayerKey(p),candidates=[r?.targetXuid,r?.targetId,r?.targetName,r?.friendXuid,r?.friendId,r?.friendName,r?.otherXuid,r?.otherId,r?.otherName];for(const v of candidates)if(clean(v))return clean(v);const ends=[r?.a,r?.b,r?.source,r?.target].filter(Boolean);for(const e of ends){const vals=[e?.xuid,e?.id,e?.name].map(clean).filter(Boolean);if(!vals.some(v=>v.toLowerCase()===k.id.toLowerCase()||v.toLowerCase()===k.name||(k.xuid&&v.toLowerCase()===k.xuid.toLowerCase())))return vals[0]??""}return ""}
function relationshipsFor(p){return [...relationships.entries()].flatMap(([providerId,list])=>(Array.isArray(list)?list:[]).filter(r=>relationTouchesPlayer(r,p)).map(r=>({providerId,...r,otherRef:relationOtherRef(r,p)})))}
function groupMembers(g){return Array.isArray(g?.members)?g.members:Array.isArray(g?.players)?g.players:[]}
function groupHasPlayer(g,p){const k=localPlayerKey(p);return groupMembers(g).some(m=>{const vals=[m?.xuid,m?.id,m?.name,typeof m==="string"?m:""].map(v=>clean(v).toLowerCase()).filter(Boolean);return vals.includes(k.id.toLowerCase())||vals.includes(k.name)||(k.xuid&&vals.includes(k.xuid.toLowerCase()))})}
function groupsFor(p){return [...groups.entries()].flatMap(([providerId,list])=>(Array.isArray(list)?list:[]).filter(g=>groupHasPlayer(g,p)).map(g=>({providerId,...g})))}
function relationshipLabel(r){return clean(r.label||r.type||r.relationship||r.status)||"Relationship"}
function groupLabel(g){return clean(g.name||g.label||g.id)||"Group"}

function findPlayer(ref){const r=clean(ref);return world.getAllPlayers().find(p=>p.id===r||p.name===r)||null}
function resolveDestination(ref){let r=clean(ref),guard=0;while(aliases.has(r)&&guard++<8)r=aliases.get(r);const matches=allPublishedNodes().filter(n=>n.id===r||n.externalId===r||`${n.providerId??""}:${n.externalId??""}`===r);return matches.sort((a,b)=>(b.providerPriority??0)-(a.providerPriority??0))[0]??null}
function destinationAvailable(n){if(!n||n.enabled===false)return false;if(n.expiresAt&&n.expiresAt<=now())return false;const s=clean(n.providerMeta?.status).toLowerCase();return !["offline","stopped","error","unavailable"].includes(s)}
function emitLifecycle(stage,p,n,extra={}){sendIpc(`transferui:transfer:${stage}`,{protocol:PROVIDER_PROTOCOL,apiVersion:API_VERSION,stage,time:now(),requestId:extra.requestId,player:{id:p.id,name:p.name},destination:{id:n.id,externalId:n.externalId??n.id,providerId:n.providerId??"local",name:n.name,target:n.netherNetId?{type:"nethernet",id:n.netherNetId}:{type:"bedrock",host:n.hostname,port:n.port}},...extra});}
async function runPolicies(p,n,request=requestId("policy")){const active=[...policyProviders.entries()].filter(([,x])=>x.enabled!==false).sort((a,b)=>(b[1].priority??0)-(a[1].priority??0));if(!active.length)return {result:"allow"};const expected=new Set(active.map(([k])=>k));return new Promise(resolve=>{const timer=system.runTimeout(()=>{policyPending.delete(request);apiMetrics.policyTimeouts++;resolve({result:"allow",timedOut:[...expected]})},API_LIMITS.policyTicks);policyPending.set(request,{expected,responses:[],resolve,timer});sendIpc("transferui:policy:request",{protocol:PROVIDER_PROTOCOL,apiVersion:API_VERSION,requestId:request,player:{id:p.id,name:p.name,tags:p.getTags?.()??[]},destination:{id:n.id,externalId:n.externalId??n.id,providerId:n.providerId??"local",name:n.name,metadata:n.providerMeta?.raw??{}},time:now()},request)})}
function finishPolicy(id){const q=policyPending.get(id);if(!q||q.expected.size)return;system.clearRun(q.timer);policyPending.delete(id);const ranked=q.responses.sort((a,b)=>(finite(b.priority,policyProviders.get(b.providerId)?.priority??0)-finite(a.priority,policyProviders.get(a.providerId)?.priority??0)));const deny=ranked.find(x=>x.result==="deny"),redirect=ranked.find(x=>x.result==="redirect"&&x.destinationId);q.resolve(deny??redirect??{result:"allow"})}
function selectDestination(criteria={}){let xs=providerNodeList().filter(destinationAvailable);if(Array.isArray(criteria.tags)&&criteria.tags.length)xs=xs.filter(n=>criteria.tags.every(t=>(n.tags??[]).includes(t)));if(criteria.providerId)xs=xs.filter(n=>n.providerId===criteria.providerId);if(criteria.region)xs=xs.filter(n=>n.region===criteria.region);if(criteria.requireCapacity)xs=xs.filter(n=>n.providerMeta?.maxPlayers==null||finite(n.providerMeta.players)<finite(n.providerMeta.maxPlayers));xs.sort((a,b)=>criteria.lowestPopulation?(finite(a.providerMeta?.players)-finite(b.providerMeta?.players)):((b.providerPriority??0)-(a.providerPriority??0)));return xs[0]??null}
function providerRemove(id){providers.delete(id);providerNodes.delete(id);presence.delete(id);relationships.delete(id);groups.delete(id);navSections.delete(id);providerActions.delete(id);policyProviders.delete(id);providerHealth.delete(id);providerTransactions.delete(id);for(const k of [...revisions.keys()])if(k.startsWith(`${id}:`))revisions.delete(k);emitProviderStatus()}
function handleApiEvent(ev){const x=receiveIpc(ev.id,ev.message);if(!x)return;try{
if(ev.id==="transferui:provider:register"){const id=clean(x.id);if(!validProviderId(id)||Number(x.protocol)!==PROVIDER_PROTOCOL||providers.size>=API_LIMITS.maxProviders&&!providers.has(id))return apiReject("Provider registration rejected");const capabilities=Array.isArray(x.capabilities)?x.capabilities.filter(c=>CAPABILITIES.has(clean(c))).map(clean):[];providers.set(id,{...x,id,name:clean(x.name).slice(0,96)||id,protocol:PROVIDER_PROTOCOL,apiVersion:API_VERSION,priority:finite(x.priority,0),capabilities,configure:x.configure&&typeof x.configure==="object"?{label:clean(x.configure.label).slice(0,64)||"Configure",adminOnly:x.configure.adminOnly!==false}:null,lastSeen:now()});providerHealth.set(id,{state:"ready",lastSeen:now(),message:""});emitProviderStatus(id)}
else if(ev.id==="transferui:provider:heartbeat"||ev.id==="transferui:provider:health"){const id=ensureProvider(x.providerId||x.id,"health");if(!id)return;providerHealth.set(id,{state:clean(x.state).slice(0,32)||"ready",lastSeen:now(),message:clean(x.message).slice(0,240),latency:x.latency??null,metadata:metadataOk(x.metadata)?x.metadata??{}:{}});providers.get(id).lastSeen=now()}
else if(ev.id==="transferui:provider:transaction:begin"){const id=ensureProvider(x.providerId);if(id)providerTransactions.set(id,{id:clean(x.transactionId)||requestId("txn"),destinations:null,presence:null,created:now()})}
else if(ev.id==="transferui:provider:transaction:commit"){const id=ensureProvider(x.providerId),t=id&&providerTransactions.get(id);if(!t||clean(x.transactionId)!==t.id)return;if(t.destinations)snapshotDestinations(id,t.destinations);if(t.presence)snapshotPresence(id,t.presence);providerTransactions.delete(id)}
else if(ev.id==="transferui:provider:destinations"||ev.id==="transferui:destination:snapshot"){const id=ensureProvider(x.providerId,"destinations");if(!id||!Array.isArray(x.destinations)||!validRevision(id,"destinations",x.revision))return;const t=providerTransactions.get(id);if(t)t.destinations=x.destinations;else snapshotDestinations(id,x.destinations);for(const [oldId,newId] of Object.entries(x.aliases??{}))aliases.set(clean(oldId),`provider:${id}:${clean(newId)}`)}
else if(ev.id==="transferui:destination:upsert"){const id=ensureProvider(x.providerId,"destination-deltas");if(id&&validRevision(id,"destinations",x.revision))upsertDestinations(id,Array.isArray(x.destinations)?x.destinations:[x.destination].filter(Boolean))}
else if(ev.id==="transferui:destination:remove"){const id=ensureProvider(x.providerId,"destination-deltas");if(!id||!validRevision(id,"destinations",x.revision))return;const m=providerNodes.get(id);for(const key of (x.ids??[x.id]).slice(0,API_LIMITS.maxDestinationsPerProvider))m?.delete(clean(key))}
else if(ev.id==="transferui:provider:presence"||ev.id==="transferui:presence:snapshot"){const id=ensureProvider(x.providerId,"presence");if(!id||!validRevision(id,"presence",x.revision))return;const t=providerTransactions.get(id);if(t)t.presence=x.players;else snapshotPresence(id,x.players)}
else if(ev.id==="transferui:presence:upsert"||ev.id==="transferui:presence:join"||ev.id==="transferui:presence:move"){const id=ensureProvider(x.providerId,"presence-deltas");if(!id||!validRevision(id,"presence",x.revision))return;const m=presenceMap(id);for(const v of (x.players??[x.player]).slice(0,API_LIMITS.maxPresencePerProvider)){const q=normalizePresence(id,v);if(q?.id)m.set(q.id,q)}}
else if(ev.id==="transferui:presence:remove"||ev.id==="transferui:presence:leave"){const id=ensureProvider(x.providerId,"presence-deltas");if(!id||!validRevision(id,"presence",x.revision))return;const m=presenceMap(id);for(const key of (x.ids??[x.id]).slice(0,API_LIMITS.maxPresencePerProvider))m.delete(clean(key))}
else if(ev.id==="transferui:relationships:snapshot"){const id=ensureProvider(x.providerId,"relationships");if(id&&Array.isArray(x.relationships)&&x.relationships.length<=API_LIMITS.maxRelationshipsPerProvider)relationships.set(id,x.relationships)}
else if(ev.id==="transferui:groups:snapshot"){const id=ensureProvider(x.providerId,"groups");if(id&&Array.isArray(x.groups)&&x.groups.length<=API_LIMITS.maxGroupsPerProvider)groups.set(id,x.groups)}
else if(ev.id==="transferui:navigation:snapshot"){const id=ensureProvider(x.providerId,"navigation");if(id&&Array.isArray(x.sections)&&x.sections.length<=API_LIMITS.maxSectionsPerProvider)navSections.set(id,x.sections)}
else if(ev.id==="transferui:actions:register"){const id=ensureProvider(x.providerId,"actions");if(id&&Array.isArray(x.actions)&&x.actions.length<=API_LIMITS.maxActionsPerProvider)providerActions.set(id,x.actions)}
else if(ev.id==="transferui:policy:register"){const id=ensureProvider(x.providerId,"policies");if(id)policyProviders.set(id,{priority:finite(x.priority,0),enabled:x.enabled!==false})}
else if(ev.id==="transferui:policy:response"){const q=policyPending.get(clean(x.requestId));if(!q)return;const id=clean(x.providerId);if(!q.expected.has(id)||!["allow","deny","redirect"].includes(x.result))return;q.expected.delete(id);q.responses.push({...x,providerId:id});finishPolicy(clean(x.requestId))}
else if(ev.id==="transferui:provider:remove"){const id=clean(x.providerId);if(providers.has(id))providerRemove(id)}
else if(ev.id==="transferui:control"){const action=clean(x.action),req=clean(x.requestId)||requestId("ctl");if(action==="status")emitProviderStatus(req);else if(action==="snapshot")sendIpc("transferui:snapshot",{protocol:PROVIDER_PROTOCOL,apiVersion:API_VERSION,requestId:req,providers:[...providers.values()].map(providerSummary),destinations:providerNodeList(),presence:[...presence.values()].flatMap(m=>[...m.values()]),relationships:[...relationships.entries()],groups:[...groups.entries()],navigation:[...navSections.entries()],actions:[...providerActions.entries()],metrics:{...apiMetrics}},req);else if(action==="select"){const n=selectDestination(x.criteria??{});sendIpc("transferui:selection",{requestId:req,destination:n},req)}else if(action==="open"){const p=findPlayer(x.player);if(p)later(()=>showFolder(p,x.folderId??null))}else if(action==="transfer"){const p=findPlayer(x.player),n=resolveDestination(x.destinationId);if(p&&n)later(()=>connect(p,n))}}
}catch(e){apiMetrics.invalid++;apiMetrics.lastError=`${e?.message??e}`.slice(0,240);console.warn(`[${PACK}] provider event failed (${ev.id}): ${e?.stack??e}`)}}
// Keep the ScriptEvent callback deliberately tiny. Bedrock can interrupt callbacks that do too much work.
// Copy only primitive event data into a bounded queue and process it over subsequent ticks.
function enqueueApiEvent(ev){
  if(!ev.id.startsWith("transferui:"))return;
  if(apiEventQueue.length>=API_LIMITS.maxQueuedEvents){
    apiMetrics.dropped++;
    apiMetrics.lastError="Provider event queue full; newest event dropped";
    return;
  }
  apiEventQueue.push({id:ev.id,message:typeof ev.message==="string"?ev.message:""});
  apiMetrics.queued++;
  if(apiEventQueue.length>apiMetrics.queueHighWater)apiMetrics.queueHighWater=apiEventQueue.length;
}
system.afterEvents.scriptEventReceive.subscribe(enqueueApiEvent);
system.runInterval(()=>{
  let processed=0;
  while(apiEventQueue.length&&processed<API_LIMITS.maxEventsPerTick){
    const ev=apiEventQueue.shift();
    try{handleApiEvent(ev)}catch(e){
      apiMetrics.handlerErrors++;
      apiMetrics.lastError=`${e?.message??e}`.slice(0,240);
      console.warn(`[${PACK}] queued provider event failed (${ev?.id??"unknown"}): ${e?.stack??e}`);
    }
    apiMetrics.processed++;
    processed++;
  }
},1);
// Garbage collect IPC, transactions and expired live state. Stale providers retain their last snapshot.
system.runInterval(()=>{const t=now();for(const [k,v] of ipcChunks)if(t-v.created>API_LIMITS.chunkTtlMs){ipcChunks.delete(k);apiMetrics.chunkTimeouts++}for(const [id,p] of providers){const h=providerHealth.get(id)??{};if(p.lastSeen&&t-p.lastSeen>API_LIMITS.providerStaleMs&&h.state!=="stale")providerHealth.set(id,{...h,state:"stale",lastSeen:h.lastSeen??p.lastSeen,message:"Provider heartbeat is stale"});const m=providerNodes.get(id);if(m)for(const [k,n] of m)if(n.expiresAt&&n.expiresAt<=t)m.delete(k)}for(const [id,tv] of providerTransactions)if(t-tv.created>API_LIMITS.chunkTtlMs)providerTransactions.delete(id)},200);
function breadcrumb(data,parent){const names=[];let id=parent,guard=0;while(id&&guard++<12){const n=data.nodes.find(x=>x.id===id);if(!n)break;names.unshift(n.name);id=n.parentId??null}return names.length?`Network / ${names.join(" / ")}`:"Network"}
