function showPlayerDetail(p,x,back=()=>showNetworkPlayers(p)){const n=resolveDestination(x.destinationId)||resolveDestination(`${x.providerId}:${x.destinationId}`),form=new CustomForm(p,`§b§l${x.name}`).label(`§fStatus: §a${x.status||"online"}`).label(n?`§fServer: §b${n.name}`:(x.destinationId?`§fServer ID: §7${x.destinationId}`:"§7Server not reported."));if(x.providerId)form.label(`§7Presence provider: ${x.providerId}`);if(n&&destinationAvailable(n))form.divider().button(`Join ${x.name}`,()=>connect(p,n));const rels=relationshipsFor(p).filter(r=>{const q=presenceByRef(r.otherRef);return q&&(q.id===x.id||q.xuid===x.xuid||q.name===x.name)});if(rels.length)form.header("Relationships").label(rels.map(r=>`§f${relationshipLabel(r)} §8• §7${r.providerId}`).join("\n"));form.divider().button("Back",()=>later(back)).closeButton().show().catch(e=>console.warn(`[${PACK}] player detail UI failed: ${e}`))}
